local AquariumKeeper = {}
local PRODUCTS = {
    small_glass_aquarium = { name = "Majhen steklen akvarij", glassCost = 2, woodCost = 1, time = 4, cost = 50, beauty = 25, prestige = 2, happiness = 1, description = "Majhen akvarij z ribami za plemiško dvorano." },
    ornate_carved_aquarium = { name = "Izrezljan akvarij", glassCost = 3, woodCost = 2, marbleCost = 1, time = 7, cost = 140, beauty = 42, prestige = 5, happiness = 2, description = "Izrezljan akvarij z marmornim okrasjem." },
    bronze_rim_aquarium = { name = "Bronastookvirni akvarij", glassCost = 4, bronzeCost = 2, marbleCost = 1, time = 10, cost = 320, beauty = 55, prestige = 10, happiness = 3, description = "Akvarij z bronastim okvirjem za bogate dvorjane." },
    silver_filigree_aquarium = { name = "Srebrnofiligranski akvarij", glassCost = 5, silverCost = 2, marbleCost = 2, time = 13, cost = 780, beauty = 68, prestige = 18, happiness = 5, description = "Akvarij s srebrnim filigranom za visoke plemiče." },
    gold_tier_aquarium = { name = "Zlatonivojski akvarij", glassCost = 6, goldCost = 2, silverCost = 1, marbleCost = 2, jewelCost = 1, time = 17, cost = 1700, beauty = 80, prestige = 28, happiness = 8, description = "Akvarij z zlatimi okraski in dragulji za visoko plemstvo." },
    royal_grand_aquarium = { name = "Kraljevski veliki akvarij", glassCost = 10, goldCost = 3, silverCost = 2, marbleCost = 4, jewelCost = 2, pearlCost = 2, time = 24, cost = 4200, beauty = 95, prestige = 60, happiness = 13, description = "Veliki kraljevski akvarij z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    fish_house = { name = "Ribiška hiša", cost = { gold = 320, wood = 130, stone = 240, glass = 6 }, upkeep = 8, qualityBonus = 5 },
    aquatic_salon = { name = "Vodna dvorana", cost = { gold = 1100, wood = 280, stone = 480, glass = 14, marble = 6 }, upkeep = 28, qualityBonus = 18 },
    marine_atelier = { name = "Morski atelje", cost = { gold = 2600, wood = 360, stone = 700, silver = 36, glass = 22 }, upkeep = 65, qualityBonus = 30 },
    royal_aquatic_palace = { name = "Kraljevska vodna palača", cost = { gold = 11500, wood = 600, stone = 1100, gold = 70, jewel = 20, glass = 40 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
AquariumKeeper.glassStock = 18; AquariumKeeper.woodStock = 14; AquariumKeeper.marbleStock = 10; AquariumKeeper.bronzeStock = 8; AquariumKeeper.silverStock = 8; AquariumKeeper.goldStock = 6; AquariumKeeper.jewelStock = 6; AquariumKeeper.pearlStock = 4
AquariumKeeper.productStock = {}; AquariumKeeper.buildings = {}; AquariumKeeper.maker = nil; AquariumKeeper.activeMaking = {}; AquariumKeeper.totalProducts = 0; AquariumKeeper.dayTimer = 0
function AquariumKeeper.init() AquariumKeeper.glassStock=18; AquariumKeeper.woodStock=14; AquariumKeeper.marbleStock=10; AquariumKeeper.bronzeStock=8; AquariumKeeper.silverStock=8; AquariumKeeper.goldStock=6; AquariumKeeper.jewelStock=6; AquariumKeeper.pearlStock=4; AquariumKeeper.productStock={}; AquariumKeeper.buildings={}; AquariumKeeper.maker=nil; AquariumKeeper.activeMaking={}; AquariumKeeper.totalProducts=0; AquariumKeeper.dayTimer=0; print("[AquariumKeeper] Royal Aquarium Keeper System initialized (6 products, 4 buildings)") end
function AquariumKeeper.hireMaker(n,s) s=s or math.random(55,90); local c=560+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; AquariumKeeper.maker={name=n or ("Akvarist "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Akvarist najet: %s (spretnost: %d)",AquariumKeeper.maker.name,s),"success") end; return true end
function AquariumKeeper.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function AquariumKeeper.build(id) local ok,e=AquariumKeeper.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(AquariumKeeper.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function AquariumKeeper.getQualityBonus() local b=0; for _,bd in ipairs(AquariumKeeper.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function AquariumKeeper.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.glassCost and AquariumKeeper.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.woodCost and AquariumKeeper.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.marbleCost and AquariumKeeper.marbleStock<(d.marbleCost or 0) then return false,"Premalo marmorja" end; if d.bronzeCost and AquariumKeeper.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.silverCost and AquariumKeeper.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and AquariumKeeper.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and AquariumKeeper.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and AquariumKeeper.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #AquariumKeeper.buildings==0 then return false,"Potrebna ribiška hiša" end; if not AquariumKeeper.maker then return false,"Potreben akvarist" end; return true end
function AquariumKeeper.make(pt,qty) qty=qty or 1; local ok,e=AquariumKeeper.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.glassCost then AquariumKeeper.glassStock=AquariumKeeper.glassStock-d.glassCost*qty end; if d.woodCost then AquariumKeeper.woodStock=AquariumKeeper.woodStock-d.woodCost*qty end; if d.marbleCost then AquariumKeeper.marbleStock=AquariumKeeper.marbleStock-d.marbleCost*qty end; if d.bronzeCost then AquariumKeeper.bronzeStock=AquariumKeeper.bronzeStock-d.bronzeCost*qty end; if d.silverCost then AquariumKeeper.silverStock=AquariumKeeper.silverStock-d.silverCost*qty end; if d.goldCost then AquariumKeeper.goldStock=AquariumKeeper.goldStock-d.goldCost*qty end; if d.jewelCost then AquariumKeeper.jewelStock=AquariumKeeper.jewelStock-d.jewelCost*qty end; if d.pearlCost then AquariumKeeper.pearlStock=AquariumKeeper.pearlStock-d.pearlCost*qty end; local t=d.time; if AquariumKeeper.maker then t=math.max(1,t-math.floor(AquariumKeeper.maker.skill/12)) end; table.insert(AquariumKeeper.activeMaking,{id="aquarium_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function AquariumKeeper.completeMaking(m) local q=1.0+(AquariumKeeper.getQualityBonus()/100); if AquariumKeeper.maker then q=q+(AquariumKeeper.maker.skill/150) end; q=math.min(2.5,q); AquariumKeeper.productStock[m.productType]=(AquariumKeeper.productStock[m.productType] or 0)+m.quantity; AquariumKeeper.totalProducts=AquariumKeeper.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if AquariumKeeper.maker then AquariumKeeper.maker.itemsMade=AquariumKeeper.maker.itemsMade+m.quantity; if math.random()<0.25 then AquariumKeeper.maker.skill=math.min(100,AquariumKeeper.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Akvarij izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"aquarium.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function AquariumKeeper.update(dt) if not _G.state then return end; AquariumKeeper.dayTimer=AquariumKeeper.dayTimer+dt; if AquariumKeeper.dayTimer>=30 then AquariumKeeper.dayTimer=0; for i=#AquariumKeeper.activeMaking,1,-1 do local m=AquariumKeeper.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then AquariumKeeper.completeMaking(m); table.remove(AquariumKeeper.activeMaking,i) end end; local tu=0; for _,bd in ipairs(AquariumKeeper.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if AquariumKeeper.maker then tu=tu+16 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function AquariumKeeper.getStats() return {glassStock=AquariumKeeper.glassStock,woodStock=AquariumKeeper.woodStock,marbleStock=AquariumKeeper.marbleStock,bronzeStock=AquariumKeeper.bronzeStock,silverStock=AquariumKeeper.silverStock,goldStock=AquariumKeeper.goldStock,jewelStock=AquariumKeeper.jewelStock,pearlStock=AquariumKeeper.pearlStock,productStock=AquariumKeeper.productStock,numBuildings=#AquariumKeeper.buildings,hasMaker=AquariumKeeper.maker~=nil,makerName=AquariumKeeper.maker and AquariumKeeper.maker.name or "—",makerSkill=AquariumKeeper.maker and AquariumKeeper.maker.skill or 0,activeMaking=#AquariumKeeper.activeMaking,totalProducts=AquariumKeeper.totalProducts} end
return AquariumKeeper
